 data.forEach((d,i)=>{for(const g of [asset.children[i].geometry,meshes[i].geometry]){g.setAttribute('skinIndex',new THREE.Uint16BufferAttribute(d.indices,4));g.setAttribute('skinWeight',new THREE.Float32BufferAttribute(d.weights,4));}meshes[i].geometry.boundingSphere=null;meshes[i].boundingSphere=null;});updateWeightView();
