  const points=bindMarkers.map(v=>new THREE.Vector3(...v)),computed=[];
  for(const mesh of asset.children)computed.push(await weightGeometry(mesh.geometry,points));
  const meshes=model.children.filter(m=>m.isSkinnedMesh);
