async function exportGLB(){if(!state.rigged||state.busy)return;state.playing=false;busy(true,'Preparando GLB com rig e animação…');const pose=capturePose(skeleton);try{clearWeightView();applyPose(skeleton,bindPose);const clip=makeClip(state.keys,state.duration);const buffer=await new GLTFExporter().parseAsync(model,{binary:true,animations:clip?[clip]:[],onlyVisible:true});download(buffer,'riglab-personagem.glb','model/gltf-binary');toast('GLB exportado com esqueleto'+(clip?' e animação.':'.'));}catch(e){toast('Falha ao exportar: '+e.message,true);}finally{applyPose(skeleton,pose);busy(false);updateWeightView();}}
const toBase64=buffer=>{let s='';const bytes=new Uint8Array(buffer);for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s);};
async function saveProject(){if(state.busy)return;state.playing=false;busy(true,'Salvando projeto…');try{const glb=await new GLTFExporter().parseAsync(asset,{binary:true});const data={format:'riglab',version:1,name:state.name,sourceKind,asset:toBase64(glb),weights:state.rigged?captureWeights():undefined,state:snapshot()};download(JSON.stringify(data),'personagem.riglab','application/json');$('#status').textContent='● Projeto salvo';toast('Projeto salvo. Use Abrir projeto para continuar depois.');}catch(e){toast(e.message,true);}finally{busy(false);}}
function loader(){const manager=new THREE.LoadingManager();manager.setURLModifier(url=>{if(url.startsWith('blob:')||url.startsWith('data:'))return url;throw new Error('Use um GLB autocontido, com texturas e geometria incorporadas.');});return new GLTFLoader(manager);}
async function importFile(file){if(!file||state.busy)return;if(!file.name.toLowerCase().endsWith('.glb'))return toast('Selecione um arquivo .glb. Imagens são apenas referências.',true);if(file.size>30*1024*1024)return toast('Limite do protótipo: arquivo GLB de até 30 MB.',true);busy(true,'Importando modelo…');try{const gltf=await loader().parseAsync(await file.arrayBuffer(),'');const normalized=normalize(gltf.scene);loadAsset(normalized,file.name.replace(/\.glb$/i,''));toast('Modelo importado. Confira a orientação antes de ajustar o rig.');}catch(e){toast('Não foi possível importar: '+e.message,true);}finally{busy(false);$('#model-file').value='';}}
function validateProject(p){if(p?.format!=='riglab'||p.version!==1||typeof p.asset!=='string'||typeof p.name!=='string')throw new Error('Formato de projeto inválido.');const s=p.state;const vec=(v,n)=>Array.isArray(v)&&v.length===n&&v.every(x=>typeof x==='number'&&Number.isFinite(x)&&Math.abs(x)<1000);const pose=p=>Array.isArray(p)&&p.length===JOINTS.length&&p.every(v=>vec(v.p,3)&&vec(v.q,4)&&Math.hypot(...v.q)>.5&&Math.hypot(...v.q)<1.5);if(!s||!Array.isArray(s.markers)||s.markers.length!==19||!s.markers.every(v=>vec(v,3))||!Number.isFinite(s.duration)||s.duration<.4||s.duration>30||!Number.isFinite(s.time)||s.time<0||s.time>s.duration||!['import','rig','animate'].includes(s.stage)||typeof s.rigged!=='boolean'||(s.stage==='animate'&&!s.rigged)||!Array.isArray(s.keys)||s.keys.length>1000||!s.keys.every(k=>Number.isFinite(k.time)&&k.time>=0&&k.time<=s.duration&&pose(k.pose))||(s.rigged&&(!pose(s.pose)||!Array.isArray(s.bindMarkers)||s.bindMarkers.length!==19||!s.bindMarkers.every(v=>vec(v,3)))))throw new Error('O projeto contém dados de rig ou animação inválidos.');}
async function openProject(file){if(!file||state.busy)return;if(file.size>80*1024*1024)return toast('Projeto maior que o limite de 80 MB.',true);busy(true,'Abrindo projeto…');try{const p=JSON.parse(await file.text());validateProject(p);const bytes=Uint8Array.from(atob(p.asset),c=>c.charCodeAt(0));const gltf=await loader().parseAsync(bytes.buffer,'');const normalized=normalize(gltf.scene);loadAsset(normalized,p.name,p.sourceKind==='demo'?'demo':'import');state.markers=p.state.markers.map(v=>new THREE.Vector3(...v));if(p.state.rigged){state.markers=p.state.bindMarkers.map(v=>new THREE.Vector3(...v));const computed=[];for(const mesh of asset.children)computed.push(await weightGeometry(mesh.geometry));asset.children.forEach((m,i)=>{m.geometry.setAttribute('skinIndex',new THREE.Uint16BufferAttribute(computed[i].indices,4));m.geometry.setAttribute('skinWeight',new THREE.Float32BufferAttribute(computed[i].weights,4));});replaceModel(true);if(p.weights)installWeights(p.weights);}restore(p.state);history=[];future=[];toast('Projeto restaurado com modelo, rig e poses.');}catch(e){toast('Não foi possível abrir: '+e.message,true);}finally{busy(false);$('#project-file').value='';}}

$('#auto-rig').onclick=generateRig;$('#refine-weights').onclick=refineWeights;$('#import').onclick=()=>$('#model-file').click();$('#model-file').onchange=e=>importFile(e.target.files[0]);$('#demo').onclick=()=>{if(!state.busy)loadAsset(normalize(createDemo()),'Sentinela da floresta','demo');};$('#open-project').onclick=()=>$('#project-file').click();$('#project-file').onchange=e=>openProject(e.target.files[0]);$('#save-project').onclick=saveProject;$('#export').onclick=exportGLB;
$$('[data-stage]').forEach(b=>b.onclick=()=>setStage(b.dataset.stage));$('#start-rig').onclick=()=>setStage('rig');$('#edit-rig').onclick=()=>{setStage('rig');toast('Ao gerar novamente, o rig e o clipe serão substituídos.');};
$('#joint-select').onchange=e=>selectJoint(e.target.value);$('#frame-camera').onclick=()=>frameCamera();$('#front-camera').onclick=()=>frameCamera(true);
function setTool(tool){if(state.stage==='import')return;state.tool=tool;updateUI();}
$('#tool-rotate').onclick=()=>setTool('rotate');$('#tool-move').onclick=()=>setTool('move');$('#fk-mode').onclick=()=>setTool('rotate');$('#ik-mode').onclick=()=>setTool('move');
$('#weights-toggle').onclick=()=>{state.showWeights=!state.showWeights;if(!state.showWeights)state.painting=false;updateWeightView();updateGizmo();};
$('#skeleton-toggle').onclick=()=>{state.showSkeleton=!state.showSkeleton;$('#skeleton-toggle').classList.toggle('active',state.showSkeleton);updateVisual();updateGizmo();};$('#wire-toggle').onclick=()=>{state.wire=!state.wire;$('#wire-toggle').classList.toggle('active',state.wire);model.traverse(m=>{if(m.isMesh)materials(m).forEach(v=>v.wireframe=state.wire);});};$('#grid-toggle').onclick=()=>{grid.visible=!grid.visible;ring.visible=grid.visible;$('#grid-toggle').classList.toggle('active',grid.visible);};
for(const axis of ['x','y','z'])$(`#axis-${axis}`).onchange=e=>{const n=Number(e.target.value);if(!Number.isFinite(n)||Math.abs(n)>100)return updateFields();record();state.playing=false;if(state.stage==='rig'){const v=state.markers[state.selected].clone();v[axis]=n;applyMarkerMove(v);}else if(state.rigged&&state.tool==='rotate'){skeleton.bones[state.selected].rotation[axis]=THREE.MathUtils.degToRad(n);skeleton.bones[0].updateMatrixWorld(true);}else if(state.rigged){const v=skeleton.bones[state.selected].getWorldPosition(new THREE.Vector3());v[axis]=n;moveIK(v);}updateVisual();updateGizmo();updateFields();};
function resetMarkers(){record();state.markers=defaultMarkers(2,$('#rest-type').value,THREE.MathUtils.clamp(Number($('#rig-width').value)||1,.5,1.5));updateUI();}$('#rest-type').onchange=resetMarkers;$('#rig-width').onchange=resetMarkers;
function rotateAsset(axis){if(state.busy)return;asset.rotation[axis]+=Math.PI/2;const next=normalize(asset);loadAsset(next,state.name,sourceKind);state.stage='import';updateUI();}$('#turn-model').onclick=()=>rotateAsset('y');$('#upright-model').onclick=()=>rotateAsset('x');
$('#undo').onclick=undo;$('#redo').onclick=redo;$('#neutral').onclick=()=>{record();state.playing=false;applyPose(skeleton,bindPose);updateUI();};$('#wave').onclick=makeWave;$('#walk').onclick=makeWalk;$('#idle').onclick=()=>makeMotion('idle');$('#run').onclick=()=>makeMotion('run');$('#add-key').onclick=addKey;$('#play').onclick=togglePlay;$('#rewind').onclick=()=>{state.playing=false;seek(0);updateUI();};$('#loop').onclick=()=>{state.loop=!state.loop;$('#loop').classList.toggle('active',state.loop);};
$('#copy-key').onclick=()=>{clipboard=capturePose(skeleton);updateUI();toast('Pose copiada. Escolha o tempo e cole.');};$('#paste-key').onclick=()=>{if(!clipboard)return;record();state.playing=false;applyPose(skeleton,clipboard);state.keys=state.keys.filter(k=>Math.abs(k.time-state.time)>.02);state.keys.push({time:state.time,pose:structuredClone(clipboard)});updateUI();};$('#delete-key').onclick=()=>{record();state.keys=state.keys.filter(k=>Math.abs(k.time-state.time)>.02);updateUI();};
$('#duration').onchange=e=>{const next=THREE.MathUtils.clamp(Number(e.target.value)||3,.4,30);record();state.playing=false;const factor=next/state.duration;state.keys.forEach(k=>k.time=k.time*factor);state.time*=factor;state.duration=next;e.target.value=next;updateUI();};
$$('[data-reference]').forEach(b=>b.onclick=()=>{const [file,name]=refs[b.dataset.reference];$('#reference-title').textContent=name;$('#reference-image').src=`${import.meta.env.BASE_URL}references/${file}.jpg`;$('#reference-image').alt=name;$('#reference-dialog').showModal();});$('#close-reference').onclick=()=>$('#reference-dialog').close();
viewport.addEventListener('dragover',e=>e.preventDefault());viewport.addEventListener('drop',e=>{e.preventDefault();importFile(e.dataTransfer.files[0]);});
window.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName)||$('#reference-dialog').open||state.busy)return;const key=e.key.toLowerCase();if((e.ctrlKey||e.metaKey)&&key==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if(e.code==='Space'){e.preventDefault();togglePlay();}if(key==='k')addKey();if(key==='r'&&state.stage==='animate')setTool('rotate');if(key==='g')setTool('move');if(key==='f')frameCamera();});
const clock=new THREE.Clock();function tick(){requestAnimationFrame(tick);const delta=Math.min(clock.getDelta(),.1);if(state.playing&&state.rigged){state.time+=delta;if(state.time>state.duration){if(state.loop)state.time%=state.duration;else{state.time=state.duration;state.playing=false;updateUI();}}const pose=samplePose(state.keys,state.time);if(pose)applyPose(skeleton,pose);updateVisual();updateTimeUI();}if(!gizmo.dragging&&!stroke)orbit.update();if(state.painting&&brushPointer){const now=performance.now();if(stroke&&now-stroke.last>=33){paintAt(brushPointer,Math.min((now-stroke.last)/1000,.1)*3);stroke.last=now;}updateBrushCursor();}renderer.render(scene,camera);}loadAsset(normalize(createDemo()),'Sentinela da floresta','demo');tick();
// Read-only diagnostics for integration tests and support; no editor internals exposed.
window.riglabDiagnostics=()=>({stage:state.stage,rigged:state.rigged,bones:skeleton?.bones.length||0,keyframes:state.keys.length,time:state.time,name:state.name,vertices:asset.children.reduce((n,m)=>n+m.geometry.attributes.position.count,0),selected:JOINTS[state.selected][0],joint:skeleton?.bones[state.selected].getWorldPosition(new THREE.Vector3()).toArray(),pose:skeleton?capturePose(skeleton):null});
